// Fetch Entire checkpoint data from a git URL or local path (DESIGN.md §"Ingest").
// Partial clone, then the `entire/checkpoints/v1` branch, else `refs/entire/checkpoints/*`.

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

export type Backend = "branch" | "refs" | "none";

export interface FetchResult {
  repoPath: string;
  backend: Backend;
  headSha: string;
}

export interface FetchOptions {
  cacheDir: string;
  /** Extra attempts after the first one. Default 2. */
  retries?: number;
  /** Base backoff in ms, doubled per retry. Default 1000. */
  backoffMs?: number;
  log?: (msg: string) => void;
}

export const CHECKPOINT_BRANCH = "entire/checkpoints/v1";
export const CHECKPOINT_REFS = "refs/entire/checkpoints/";
const META_FILE = "roster-fetch.json";

type RetryOpts = Required<Omit<FetchOptions, "cacheDir">>;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function git(args: string[], cwd?: string): Promise<string> {
  const proc = Bun.spawn(["git", ...args], {
    cwd,
    stdout: "pipe",
    stderr: "pipe",
    env: { ...process.env, GIT_TERMINAL_PROMPT: "0" },
  });
  const [out, err, code] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
    proc.exited,
  ]);
  if (code !== 0) throw new Error("git " + args[0] + " failed (" + code + "): " + err.trim());
  return out;
}

/** Run `fn`, retrying on failure with exponential backoff; every attempt is logged. */
async function withRetry<T>(label: string, fn: () => Promise<T>, o: RetryOpts): Promise<T> {
  const total = o.retries + 1;
  for (let attempt = 1; ; attempt++) {
    o.log("[fetch] " + label + ": attempt " + attempt + "/" + total);
    try {
      return await fn();
    } catch (e) {
      if (attempt >= total) throw e;
      o.log("[fetch] " + label + ": attempt " + attempt + " failed (" + (e as Error).message + "); retrying");
      await sleep(o.backoffMs * 2 ** (attempt - 1));
    }
  }
}

const isRemote = (s: string) => /^[a-z][a-z0-9+.-]*:\/\//i.test(s) || /^[\w.-]+@[\w.-]+:/.test(s);

export async function fetchCheckpoints(source: string, opts: FetchOptions): Promise<FetchResult> {
  const o: RetryOpts = { retries: 2, backoffMs: 1000, log: (m) => console.error(m), ...opts };
  const src = isRemote(source) ? source : resolve(source);
  const branchRef = "refs/heads/" + CHECKPOINT_BRANCH;

  // One round trip: remote HEAD plus the two places checkpoint data can live.
  const lsOut = await withRetry("ls-remote", () => git(["ls-remote", src, "HEAD", branchRef, CHECKPOINT_REFS + "*"]), o);
  const lines = lsOut
    .split("\n")
    .filter(Boolean)
    .map((l) => l.split("\t") as [string, string]);
  const remoteHead = lines.find(([, ref]) => ref === "HEAD")?.[0] ?? "";
  const hasBranch = lines.some(([, ref]) => ref === branchRef);
  const hasRefs = lines.some(([, ref]) => ref.startsWith(CHECKPOINT_REFS));

  // Cache by URL + remote HEAD; the checkpoint refs are in the key so new checkpoints invalidate it.
  const key = createHash("sha256")
    .update(JSON.stringify([src, remoteHead, lines.filter(([, r]) => r !== "HEAD")]))
    .digest("hex")
    .slice(0, 24);
  const cacheDir = resolve(opts.cacheDir);
  const repoPath = join(cacheDir, key);
  const metaPath = join(repoPath, ".git", META_FILE);
  if (existsSync(metaPath)) {
    o.log("[fetch] cache hit " + key);
    return JSON.parse(readFileSync(metaPath, "utf8")) as FetchResult;
  }

  mkdirSync(cacheDir, { recursive: true });
  const tmp = repoPath + ".tmp-" + process.pid;
  await withRetry(
    "clone",
    async () => {
      rmSync(tmp, { recursive: true, force: true });
      await git(["clone", "--quiet", "--filter=blob:none", "--no-checkout", src, tmp]);
    },
    o,
  );

  let backend: Backend = "none";
  if (hasBranch) {
    const spec = "+" + CHECKPOINT_BRANCH + ":" + CHECKPOINT_BRANCH;
    await withRetry("fetch branch", () => git(["fetch", "--quiet", "origin", spec], tmp), o);
    backend = "branch";
  } else if (hasRefs) {
    const spec = "+" + CHECKPOINT_REFS + "*:" + CHECKPOINT_REFS + "*";
    await withRetry("fetch refs", () => git(["fetch", "--quiet", "origin", spec], tmp), o);
    backend = "refs";
  } else {
    o.log("[fetch] no Entire data: run `entire enable` in the source repo and push the checkpoints branch");
  }

  let headSha = "";
  try {
    headSha = (await git(["rev-parse", "HEAD"], tmp)).trim();
  } catch {
    // empty repository: no HEAD
  }

  const result: FetchResult = { repoPath, backend, headSha };
  writeFileSync(join(tmp, ".git", META_FILE), JSON.stringify(result));
  rmSync(repoPath, { recursive: true, force: true });
  renameSync(tmp, repoPath);
  return result;
}

// Parse Entire checkpoints into Session rows. See docs/DESIGN.md §"Entire checkpoint format" and §"Ingest".
import { createHash } from "node:crypto";
import { basename } from "node:path";
import type { Session, SessionSource } from "../types";

export type Backend = SessionSource | "auto";

/** Where tokens and model came from. Session.source is the storage backend, so this lives beside it. */
export type UsageSource = "metadata" | "transcript" | "none";

export interface ParsedSession extends Session {
  usage_source: UsageSource;
  model_source: "metadata" | "transcript" | "none";
}

export interface ParseOptions {
  warn?: (msg: string) => void;
}

const BRANCH_REFS = ["refs/heads/entire/checkpoints/v1", "refs/remotes/origin/entire/checkpoints/v1"];
const PROMPT_SEP = "\n\n---\n\n";

function git(repo: string, args: string[]): string | null {
  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  return p.exitCode === 0 ? p.stdout.toString() : null;
}

/** A checkpoint's files, keyed by path relative to the checkpoint root. */
interface RawCheckpoint {
  id: string;
  source: SessionSource;
  read: (path: string) => string | null;
  paths: string[];
}

function makeReader(repo: string, treeish: string, prefix: string) {
  return (path: string) => git(repo, ["show", `${treeish}:${prefix}${path}`]);
}

function listBranch(repo: string): RawCheckpoint[] {
  for (const ref of BRANCH_REFS) {
    const out = git(repo, ["ls-tree", "-r", "--name-only", ref]);
    if (!out) continue;
    const byId = new Map<string, string[]>();
    for (const p of out.split("\n").filter(Boolean)) {
      const m = /^([0-9a-f]{2})\/([^/]+)\/(.+)$/.exec(p);
      if (!m) continue;
      const id = m[1]! + m[2]!;
      (byId.get(id) ?? byId.set(id, []).get(id)!).push(m[3]!);
    }
    if (byId.size === 0) continue;
    return [...byId].map(([id, paths]) => ({
      id,
      source: "branch" as const,
      paths,
      read: makeReader(repo, ref, `${id.slice(0, 2)}/${id.slice(2)}/`),
    }));
  }
  return [];
}

function listRefs(repo: string): RawCheckpoint[] {
  const out = git(repo, ["for-each-ref", "--format=%(refname)", "refs/entire/checkpoints/"]);
  if (!out) return [];
  const res: RawCheckpoint[] = [];
  for (const ref of out.split("\n").filter(Boolean)) {
    const tree = git(repo, ["ls-tree", "-r", "--name-only", ref]);
    if (tree === null) continue;
    res.push({
      id: ref.split("/").pop()!,
      source: "git-refs",
      paths: tree.split("\n").filter(Boolean),
      read: makeReader(repo, ref, ""),
    });
  }
  return res;
}

/** checkpoint id → [commit sha, unix time] of the earliest commit carrying its trailer, on any branch. */
function mapCommits(repo: string): Map<string, string> {
  const out = git(repo, ["log", "--all", "--format=%H%x1f%ct%x1f%(trailers:key=Entire-Checkpoint,valueonly,separator=%x2c)%x1e"]);
  const best = new Map<string, { sha: string; t: number }>();
  for (const rec of (out ?? "").split("\x1e")) {
    const [sha, ct, ids] = rec.trim().split("\x1f");
    if (!sha || !ids) continue;
    for (const id of ids.split(",").map((s) => s.trim()).filter(Boolean)) {
      const t = Number(ct);
      const cur = best.get(id);
      if (!cur || t < cur.t) best.set(id, { sha, t });
    }
  }
  return new Map([...best].map(([id, v]) => [id, v.sha]));
}

function githubUrlBase(repo: string): { owner: string; name: string } | null {
  const url = git(repo, ["remote", "get-url", "origin"])?.trim() ?? "";
  const m = /github\.com[:/]([^/]+)\/([^/]+?)(?:\.git)?$/.exec(url);
  return m ? { owner: m[1]!, name: m[2]! } : null;
}

type Json = Record<string, any>;

function jsonl(text: string | null): Json[] {
  if (!text) return [];
  const rows: Json[] = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    try {
      rows.push(JSON.parse(line));
    } catch {
      // transcripts are best-effort; skip torn lines
    }
  }
  return rows;
}

const cleanModel = (m: string) => m.replace(/\[[^\]]*\]$/, "");
const hashRules = (s: string) => createHash("sha256").update(s.replace(/\r\n/g, "\n").trim()).digest("hex");

interface TranscriptInfo {
  model: string | null;
  rules_hash: string | null;
  tokens: { in: number; out: number; cr: number; cw: number } | null;
  prompts: string[];
  first_ts: string | null;
  last_ts: string | null;
}

function readTranscript(rows: Json[]): TranscriptInfo {
  let model: string | null = null;
  let attachedModel: string | null = null;
  let rules: string | null = null;
  const sum = { in: 0, out: 0, cr: 0, cw: 0 };
  let sawClaudeUsage = false;
  let codexTotal: Json | null = null;
  const prompts: string[] = [];
  const ts: string[] = [];

  for (const r of rows) {
    if (typeof r.timestamp === "string") ts.push(r.timestamp);
    if (r.type === "attachment") {
      const a = r.attachment ?? {};
      if (a.type === "model" && a.identity?.modelId) attachedModel ??= cleanModel(String(a.identity.modelId));
      if (a.type === "instructions" && rules === null) {
        const proj = (a.files ?? []).filter((f: Json) => f.type === "Project" && typeof f.content === "string");
        if (proj.length) rules = hashRules(proj.map((f: Json) => f.content).join("\n"));
      }
    } else if (r.type === "assistant" && r.message) {
      if (typeof r.message.model === "string" && r.message.model && r.message.model !== "<synthetic>") model ??= r.message.model;
      const u = r.message.usage;
